[CmdletBinding()]
param([Parameter(Mandatory)][string]$DiagnosticsPath,[Parameter(Mandatory)][string]$NativeLogPath,[Parameter(Mandatory)][string]$AILocationsPath,[Parameter(Mandatory)][string]$OutputDirectory,[string]$RevisionId='r0063')
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
function Assert($b,$s){if(!$b){throw $s}}
function Save($p,$t){$p=Join-Path $OutputDirectory $p;New-Item (Split-Path $p) -ItemType Directory -Force|Out-Null;[IO.File]::WriteAllText($p,$t.TrimEnd()+"`n",[Text.UTF8Encoding]::new($false))}
function Json($p,$o){Save $p ($o|ConvertTo-Json -Depth 70)}
function Pos($v){(@($v|ForEach-Object {([double]$_).ToString('0.000',[Globalization.CultureInfo]::InvariantCulture)}) -join ' ')}
function Field($fs,$name){$f=@($fs|Where-Object name -ceq $name);Assert ($f.Count -eq 1 -and $f[0].status -ceq 'resolved') "Missing $name";return $f[0]}
Assert (!(Test-Path $OutputDirectory)) 'Output exists'
$d=Get-Content $DiagnosticsPath -Raw|ConvertFrom-Json;$ai=Get-Content $AILocationsPath -Raw|ConvertFrom-Json;$log=Get-Content $NativeLogPath
Assert ($ai.gameVersion -ceq $d.gameVersion) 'Version mismatch'
Assert (@($log|Where-Object {$_ -match '\[ME_CA_AI_READ\] COMPLETE'}).Count -eq 1) 'Incomplete native read'
Assert (@($log|Where-Object {$_ -match ('BEGIN game='+[regex]::Escape($d.gameVersion))}).Count -eq 1) 'Native version mismatch'
$labels=@{};foreach($line in $log){if($line -match '\[ME_CA_LABEL\] (\d+)\|(.+)$'){$labels[$Matches[1]]=$Matches[2]}}
$ranks=@{supply_depots=0;control_points=1;harbors=2;starting_bases=3;settlements=4;other=5}
$records=@(foreach($e in $d.entities){$c=@($e.components|Where-Object className -ceq 'SCR_AmbientVehicleSpawnPointComponent');if(!$c.Count){continue};Assert ($c.Count -eq 1 -and $e.positionStatus -ceq 'resolved') 'Invalid point';$fs=$c[0].fields;$f=@($e.components|Where-Object className -ceq 'SCR_FactionAffiliationComponent');Assert ($f.Count -eq 1) 'Missing faction'
 $included=@((Field $fs 'm_aIncludedEditableEntityLabels').values|ForEach-Object {Assert ($labels.ContainsKey($_)) 'Unknown label';[pscustomobject]@{id=[int]$_;name=$labels[$_]}})
 $excluded=@((Field $fs 'm_aExcludedEditableEntityLabels').values|ForEach-Object {Assert ($labels.ContainsKey($_)) 'Unknown label';[pscustomobject]@{id=[int]$_;name=$labels[$_]}})
 $candidates=@(@(foreach($t in $ai.supplyLocationEvidence.destinations){foreach($anchor in $t.anchors){$dist=[math]::Sqrt([math]::Pow($e.worldPosition[0]-$anchor.position[0],2)+[math]::Pow($e.worldPosition[2]-$anchor.position[2],2));if($dist -le $anchor.radiusMeters){[pscustomobject]@{id=$t.id;name=$t.name;category=$t.category;tier=$ranks[$t.category];distanceMeters=$dist;anchorId=$anchor.sourceId;anchorPosition=$anchor.position;radiusMeters=$anchor.radiusMeters}}}})|Sort-Object tier,distanceMeters,id,anchorId)
 $location=$null;if($candidates.Count){$location=$candidates[0]}
 [pscustomobject][ordered]@{id=$e.sourceId;name=if($e.name){$e.name}else{'Vehicle_'+($e.sourceId -replace '[^0-9A-Fa-f]','')};sourceName=$e.name;parentSourceId=$e.parentSourceId;prefab=$e.prefab;subscene=$e.subscene;layer=$e.layer;worldPositionMeters=$e.worldPosition;faction=(Field $f[0].fields 'faction affiliation').value;enabled=(Field $fs 'Enabled').value -eq 'true';respawnPeriodSeconds=[int](Field $fs 'm_iRespawnPeriod').value;requireAllIncludedLabels=(Field $fs 'm_bRequireAllIncludedLabels').value -eq 'true';stopDespawnOnInteraction=(Field $fs 'm_bStopDespawnOnInteraction').value -eq 'true';saveOnDespawn=(Field $fs 'm_bSaveOnDespawn').value -eq 'true';includedLabels=$included;excludedLabels=$excluded;location=$location;locationCandidates=$candidates;fieldEvidence=$fs;vehicleCandidatesStatus='not_resolved';runtimeSpawnStatus='not_measured';ownershipEstablished=$false}
})
Assert (@($records.id|Sort-Object -Unique).Count -eq $records.Count) 'Duplicate IDs'
$snapshot="1.8.0.13/CTI_Campaign_HQC_Eden/$RevisionId"
$report=[ordered]@{schemaVersion=3;kind='ambient-vehicle-spawn-points';status='partial';snapshotId=$snapshot;gameVersion=$d.gameVersion;worldPath=$d.worldPath;sourceCapturedAtUTC=$d.generatedAtUTC;diagnosticsSha256=(Get-FileHash $DiagnosticsPath).Hash;nativeLogSha256=(Get-FileHash $NativeLogPath).Hash;locationCatalogSha256=(Get-FileHash $AILocationsPath).Hash;locationPolicy='geographic supply catalog anchors; depots 200m then CP,harbors,HQ,settlements,other 350m XZ; nearest in first tier; no tactical AI categories';normalizerVersion='ambient-vehicles-0.1';labels=$labels;pointCount=$records.Count;records=$records;limitations=@('Concrete vehicle catalog candidates not yet resolved','No runtime spawning performed','Other spawn mechanisms and placed vehicles not included')}
Json 'Vehicles/SpawnPoints.json' $report
$summary=[Collections.Generic.List[string]]::new();$summary.Add('# Точки появления машин');$summary.Add('');$summary.Add("Всего точек фонового появления техники: **$($records.Count)**. Это позиции спавна, не количество существующих машин. Конкретные модели выбираются из каталога фракции по фильтрам; список моделей пока не разрешён.");$summary.Add('');$summary.Add('## По фракциям');$summary.Add('');$summary.Add('| Фракция | Точек | Без повторного появления | Повторное появление через 10 мин |');$summary.Add('| --- | ---: | ---: | ---: |')
foreach($g in $records|Group-Object faction|Sort-Object Count -Descending){$summary.Add("| [$($g.Name)](Factions/$($g.Name).md) | $($g.Count) | $(@($g.Group|Where-Object respawnPeriodSeconds -eq 0).Count) | $(@($g.Group|Where-Object respawnPeriodSeconds -eq 600).Count) |")}
$summary.Add('');$summary.Add('## По локациям');$summary.Add('');$summary.Add('Названия и объединения взяты из справочника припасов. Склады — 200 м, остальные категории — 350 м по X/Z; ближайший якорь в первом подходящем приоритете. Это географическая привязка, не принадлежность базе. Patrols, огневые точки и Checkpoint к машинам не применяются.');$summary.Add('')
function Page($rows,$name,$withSummary=$false){$lines=[Collections.Generic.List[string]]::new();$lines.Add("# $name");$lines.Add('');$lines.Add('[Сводка](../Summary.md)');$lines.Add('');if($withSummary){$lines.Add('## Summary');$lines.Add('');$lines.Add("Всего точек: **$(@($rows).Count)**. Это количество позиций появления, не фактически созданных машин.");$lines.Add('');$lines.Add('| Фракция | Точек появления |');$lines.Add('| --- | ---: |');foreach($faction in @('CIV','FIA','US','USSR')){$n=@($rows|Where-Object faction -ceq $faction).Count;if($n){$lines.Add("| $faction | $n |")}};$lines.Add('');$lines.Add('## Точки');$lines.Add('')};if($withSummary){$lines.Add('| Фракция | Координаты X Y Z, м | Повторное появление, мин | Включённые метки | Режим | Исключённые метки |');$lines.Add('| --- | --- | ---: | --- | --- | --- |')}else{$lines.Add('| Точка | Фракция | Координаты X Y Z, м | Локация | Повторное появление, мин | Включённые метки | Режим | Исключённые метки |');$lines.Add('| --- | --- | --- | --- | ---: | --- | --- | --- |');};foreach($p in $rows|Sort-Object id){$loc='Без локации';if($p.location){$loc=$p.location.name};$period='Нет';if($p.respawnPeriodSeconds -gt 0){$period=($p.respawnPeriodSeconds/60).ToString([Globalization.CultureInfo]::InvariantCulture)};$inc=@($p.includedLabels|ForEach-Object name) -join ', ';$exc=@($p.excludedLabels|ForEach-Object name) -join ', ';$mode=if($p.requireAllIncludedLabels){'Все'}else{'Любая'};if($withSummary){$lines.Add("| $($p.faction) | $(Pos $p.worldPositionMeters) | $period | $inc | $mode | $exc |")}else{$lines.Add("| $($p.name) | $($p.faction) | $(Pos $p.worldPositionMeters) | $loc | $period | $inc | $mode | $exc |")}};$lines.Add('');$lines.Add('[Полные поля и источники](../SpawnPoints.json).');$lines -join "`n"}
foreach($g in $records|Group-Object faction){
 $lines=[Collections.Generic.List[string]]::new();$lines.Add("# $($g.Name)");$lines.Add('');$lines.Add('[Сводка](../Summary.md)');$lines.Add('');$lines.Add("Всего точек: **$($g.Count)**.");$lines.Add('');$lines.Add('> **Для проверки:** в начале показаны точки с m_iRespawnPeriod = 0 — повторное появление отключено. Это может быть намеренной настройкой; само по себе значение не доказывает ошибку.');$lines.Add('')
 foreach($repeat in @($false,$true)){$rows=@($g.Group|Where-Object {($_.respawnPeriodSeconds -gt 0) -eq $repeat});$title=if($repeat){'С повторным появлением'}else{'Без повторного появления'};$lines.Add("## $title — $($rows.Count)");$lines.Add('');if($rows.Count){$page=Page $rows $g.Name;$table=[regex]::Match($page,'(?s)\| Точка \|.*?(?=\r?\n\r?\n\[Полные)').Value;if(!$table){throw 'Table missing'};$lines.Add($table)}else{$lines.Add('Таких точек нет.')};$lines.Add('')}
 $lines.Add('[Полные поля и источники](../SpawnPoints.json).');Save "Vehicles/Factions/$($g.Name).md" ($lines -join "`n")
}
function LocationStem($name){$s=[regex]::Replace($name,'[^\p{L}\p{Nd}_-]+','-').Trim('-');if(!$s){$s='Unnamed'};if($s -match '^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$'){$s='Location-'+$s};return $s}
$locationRows=@();$groups=@($records|Group-Object {if($_.location){$_.location.id}else{'unassigned'}}|Sort-Object Name);$stemCounts=@{}
foreach($group in $groups){$label='Без локации';if($group.Group[0].location){$label=$group.Group[0].location.name};$stem=LocationStem $label;if(!$stemCounts.ContainsKey($stem)){$stemCounts[$stem]=0};$stemCounts[$stem]++}
foreach($g in $groups){$name='Без локации';$category='unassigned';if($g.Group[0].location){$name=$g.Group[0].location.name;$category=$g.Group[0].location.category};$stem=LocationStem $name;if($stemCounts[$stem] -gt 1){$sha=[Security.Cryptography.SHA256]::Create();try{$suffix=([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($g.Name)))).Replace('-','').Substring(0,8).ToLowerInvariant()}finally{$sha.Dispose()};$stem+='-'+$suffix};$file=$stem+'.md';$locationRows+=[pscustomobject]@{name=$name;category=$category;file=$file;count=$g.Count};Save "Vehicles/Locations/$file" (Page $g.Group $name $true)}
$categories=[ordered]@{control_points='Контрольные точки';harbors='Доки';supply_depots='Склады припасов';starting_bases='Стартовые базы';settlements='Города и деревни';other='Другое';unassigned='Без локации'}
foreach($category in $categories.Keys){$rows=@($locationRows|Where-Object category -ceq $category|Sort-Object name,file);if(!$rows.Count){continue};$total=($rows|Measure-Object count -Sum).Sum;$summary.Add('');$summary.Add("### $($categories[$category])");$summary.Add('');$summary.Add("Всего точек: **$total**.");$summary.Add('');$summary.Add('| Локация | Точек |');$summary.Add('| --- | ---: |');foreach($row in $rows){$summary.Add("| [$($row.name)](Locations/$($row.file)) | $($row.count) |")}}
$summary.Add('');$summary.Add('## Откуда данные и как работает появление');$summary.Add('');$summary.Add('Позиция — worldPosition сущности с SCR_AmbientVehicleSpawnPointComponent; фракция — SCR_FactionAffiliationComponent → faction affiliation. Время — m_iRespawnPeriod, секунды / 60; 0 отключает повторное появление. Фильтры — m_aIncludedEditableEntityLabels, m_aExcludedEditableEntityLabels и m_bRequireAllIncludedLabels. Имена меток прочитаны из EEditableEntityLabel установленной игры 1.8.0.13.');$summary.Add('');$summary.Add('В Update компонент получает VEHICLE-каталог фракции, вызывает GetFullFilteredEntityListWithLabels и выбирает случайный элемент. Таймер повторного появления не означает гарантированный спавн строго каждые 10 минут: система учитывает состояние машины, близость игроков, флаг SpawnVehicles и доступное место. SpawnVehicle дополнительно проверяет свободную позицию. Фактический спавн здесь не измерялся.');$summary.Add('');$summary.Add('[Канонические данные](SpawnPoints.json).');Save 'Vehicles/Summary.md' ($summary -join "`n")
Json 'world.json' ([ordered]@{schemaVersion=3;snapshotId=$snapshot;revisionId=$RevisionId;gameVersion=$d.gameVersion;worldPath=$d.worldPath;normalizerVersion='ambient-vehicles-0.1';status='partial';sourceCapturedAtUTC=$d.generatedAtUTC})
Json 'data.json' ([ordered]@{schemaVersion=3;snapshotId=$snapshot;status='partial';sections=@{vehicles=@{data='Vehicles/SpawnPoints.json';summary='Vehicles/Summary.md';status='partial'};ai=@{data='../r0057/AI/Groups.json';status='unchanged'};supplies=@{data='../r0046/data.json';status='unchanged'}}})
"Vehicle points: $($records.Count)"
